def to_minutes(t):
    h, m = map(int, t.split(":"))
    return h * 60 + m

def fmt(minutes):
    return f"{minutes // 60:02d}:{minutes % 60:02d}"

DURATION = 30
WORK_START = to_minutes("09:00")
WORK_END = to_minutes("17:00")
DAYS = ["Monday", "Tuesday"]
PARTICIPANTS = ["Jeffrey", "Harold"]
PREFERRED_TUESDAY_BEFORE = to_minutes("14:30")

blocked = {
    "Jeffrey": {
        "Monday": [],
        "Tuesday": [],
    },
    "Harold": {
        "Monday": [
            (to_minutes("09:00"), to_minutes("10:00")),
            (to_minutes("10:30"), to_minutes("17:00")),
        ],
        "Tuesday": [
            (to_minutes("09:00"), to_minutes("09:30")),
            (to_minutes("10:30"), to_minutes("11:30")),
            (to_minutes("12:30"), to_minutes("13:30")),
            (to_minutes("14:30"), to_minutes("15:30")),
            (to_minutes("16:00"), to_minutes("17:00")),
        ],
    },
}

def available(day, start, end):
    for person in PARTICIPANTS:
        for s, e in blocked[person].get(day, []):
            if start < e and end > s:
                return False
    return True

best = None
best_key = None

for day in DAYS:
    for start in range(WORK_START, WORK_END - DURATION + 1):
        end = start + DURATION
        if not available(day, start, end):
            continue
        meets_preference = day == "Tuesday" and start < PREFERRED_TUESDAY_BEFORE
        # Prefer the preferred Tuesday-before-14:30 slot, then any Tuesday over Monday, then earliest.
        key = (
            0 if meets_preference else 1,
            0 if day == "Tuesday" else 1,
            start,
        )
        if best_key is None or key < best_key:
            best_key = key
            best = (day, start, end)

print([best[0], fmt(best[1]), fmt(best[2])])
